        let gameState = {            level: 1, stage: 'home', currentStage: 'home', playerTitle: '玩家', score: 0, scoredEvents: {}, gameStartTime: null, gameEndTime: null,            hourAngle: 0, activeBlank: null, filledBlanks: [],            activeCards: [], matches: 0, cardBusy: false,            selectedItemData: null, scaleAllocations: { baoluo: [], liusu: [] },            selectedChars: [],            power: 50, pullIdx: 0, pullBusy: false,            sahibiniAlloc: { proven: [], believe: [], unknown: [] },            distance: 10, mosquitoesSwatted: 0, totalMosquitoes: 8,            poemSelections: [], dialNumber: "",            moonLusu: 42, moonLiuyuan: 58, moonNoise: 18, moonPressure: 56, moonPicked: false,            bargainRound: 0, rumor: 0, chips: { reputation: 70, body: 100, time: 60, marriage: 15, dignity: 80 }, leadership: 30, bargainSuccess: false, bargainPath: [], bargainBetAmount: 1, pendingBargainAction: null, bargainStakeWon: 0,            inventory: [], dockSelected: [], delivered: [], dockMedicineCombined: false, dockMedicineLineSaid: false, dockMedicineVerified: false, dockRaincoatUnlocked: false, dockRaincoatChoice: { color: '', material: '', clothing: '' }, dockMaskEarned: false, dockMaskRevealed: false, raidFoundItems: [], raidRoomSelected: [], raidFoundBox: false, bayFoodCollected: [], bayFoodSelected: [], babingtonUnlocked: false, babingtonIngredientSelected: [], recipeSelected: []        };        const levelBackgrounds = {            1: { url: "assets/images/yatjB4.png", label: "第一關主視覺" },            2: { url: "assets/images/Nva9HC.png", label: "第二關主視覺" },            3: { url: "assets/images/7IUYL0.png", label: "第三關主視覺" },            4: { url: "assets/images/CXBqvY.png", label: "第四關主視覺" },            5: { url: "assets/images/6OwPVT.png", label: "第五關主視覺" }        };        function setLevelBackground(level) {            const view = document.getElementById('game-view');            const caption = document.getElementById('stage-bg-caption');            const bg = levelBackgrounds[level];            if (!view || !bg) return;            view.style.backgroundImage = `url('${bg.url}')`;            if (caption) caption.innerText = bg.label;        }        // 調整後的文字矩陣 (5*12)        const gridChars = [            "活", "死", "作", "火", "與", "與", "音", "執", "白", "與", "城", "偕",            "雨", "生", "潮", "光", "燈", "子", "聲", "子", "水", "與", "傾", "偕",            "沙", "生", "海", "石", "相", "子", "亂", "之", "天", "與", "子", "子",            "海", "契", "波", "電", "足", "子", "流", "手", "柳", "戰", "白", "老",            "霧", "闊", "浪", "愛", "悅", "悅", "別", "手", "原", "流", "蘇", "老"        ];        // 數字形狀 1314 對應的目標座標 (12列排法)        const targetIndices = [            1, 13, 25, 37, 49, // 1 (死, 生, 生, 契, 闊)            4, 5, 17, 29, 41, 52, 53, // 3 (與, 與, 子, 子, 子, 悅, 悅)            7, 19, 31, 43, 55, // 1 (執, 子, 之, 手, 手)            9, 21, 33, 34, 35, 11, 23, 47, 59 // 4 (與, 與, 與, 子, 子, 偕, 偕, 老, 老)        ];        const insults = [            "我們詩禮人家，不準學跳舞的，好不害臊！",            "人家問你，說不會跳不就結了？不會也不是丟臉的事。",            "像你三媽，像我，都是大戶人家的小姐，活過這半輩子了，我們就不會跳！",            "跳了一次，說是敷衍人家的面子，還跳第二次，第三次！",            "豬油蒙了心，你若是以為你破壞了你妹子的事，你就有指望了？",            "我叫你早早的歇了這個念頭！",            "什麼世面沒見過？我們就不會跳！",            "就只她結婚之後跟她那不成材的姑爺學會了這一手！"        ];        const showMessage = (text) => {            const box = document.getElementById('message-box');            const messageTextEl = document.getElementById('message-text');            if (messageTextEl) {                messageTextEl.innerText = text;                box.classList.remove('hidden');                setTimeout(() => box.classList.add('hidden'), 3000);            }        };        const closeModal = () => { document.getElementById('detail-modal').style.display = 'none'; };        function updateScore() { document.getElementById('score').innerText = gameState.score; }        function addScore(amount, key) {            const dynamicPart = [                gameState.pullIdx, gameState.bargainRound, gameState.matches, gameState.mosquitoesSwatted,                Array.isArray(gameState.poemSelections) ? gameState.poemSelections.join('|') : '',                gameState.dialNumber || '',                Array.isArray(gameState.raidRoomSelected) ? gameState.raidRoomSelected.join('|') : '',                Array.isArray(gameState.bayFoodSelected) ? gameState.bayFoodSelected.join('|') : '',                Array.isArray(gameState.babingtonIngredientSelected) ? gameState.babingtonIngredientSelected.join('|') : '',                gameState.recipeSelected ? JSON.stringify(gameState.recipeSelected) : ''            ].join(':');            const eventKey = key || `${gameState.currentStage || 'unknown'}:${amount}:${dynamicPart}`;            if (gameState.scoredEvents[eventKey]) return;            gameState.scoredEvents[eventKey] = true;            gameState.score += amount;            updateScore();        }        function loseChips(amount, reason) {            gameState.score = Math.max(0, gameState.score - amount);            updateScore();            showMessage((reason || '判斷失誤') + `｜籌碼 -${amount}`);        }        const stageNames = {            '1-intro': '第一關首頁', '1-1': '1-1 白公館鐘面', '1-2': '1-2 破碎電報', '1-3': '1-3 白公館爭吵',            '2-intro': '第二關首頁', '2-1': '2-1 鏡中面目', '2-2': '2-2 偏見天秤', '2-3': '2-3 圓舞控訴',            '3-intro': '第三關首頁', '3-1': '3-1 淺水灣心理戰', '3-2': '3-2 薩黑荑妮檔案', '3-3': '3-3 沙灘界線',            '4-intro': '第四關首頁', '4-1': '4-1 電話古詩', '4-2': '4-2 月亮距離', '4-3': '4-3 婚姻賭局',            '5-intro': '第五關首頁', '5-1': '5-1 碼頭物件', '5-2': '5-2 空襲與淺水灣', '5-2-babington': '5-2 巴丙頓家三道菜', '5-3': '5-3 薩黑荑妮的料理', '5-3-soup-cooking': '5-3 清蒸小蠔湯烹煮',            '5-3-proposal': '告別薩黑荑妮公主', '5-3-wedding': '執子之手與子偕老', 'complete': '章節達成'        };        const stageSequence = ['1-intro','1-1','1-2','1-3','2-intro','2-1','2-2','2-3','3-intro','3-1','3-2','3-3','4-intro','4-1','4-2','4-3','5-intro','5-1','5-2','5-2-babington','5-3','5-3-soup-cooking','5-3-proposal','5-3-wedding'];        const assistContent = {            '1-1': { hint: '白公館的時間不是現在式，而是「慢了十來年」找到原文日光節約時間。', answer: '把時鐘指向十一點，也就是 11:00。' },            '1-2': { hint: '電報不是普通死訊，它會逼流蘇回到「前夫」與「守節」的位置。先找出事件，再找出白家真正盤算的利益。', answer: '依序填入：前夫／不幸過世／要人回去報喪／當個孀婦／家族臉面／盤算分刮。' },            '1-3': { hint: '這題要找「話語配對」：誰在責備、誰在冷笑、哪一句話互相呼應。先翻開兩張，再記住語氣相近的句子。', answer: '找出三組互相對應的白公館爭吵話語，全部配對成功即可過關。' },            '2-1': { hint: '鏡中的流蘇不是圓潤富態，而是帶著清冷、纖細與尖銳感。', answer: '選：身軀「纖瘦」、臉「青玉」、眼睛「清水」、下頷「尖」。' },            '2-2': { hint: '白家把寶絡當成可投資的婚姻籌碼，把流蘇當成累贅。金珠、玉鐲與七妹婚事都偏向寶絡。', answer: '寶絡：金珠細軟、翠綠玉鐲、七妹的婚事、巢絲衣料、綠寶戒指、珍珠耳墜子。流蘇：離婚身分、過時衣裳、白吃白住。' },            '2-3': { hint: '身後的冷語最後指向一個羞辱離婚女性的四字成語。', answer: '答案是：敗柳殘花。' },            '3-1': { hint: '判斷每句話是在守住自己、暫時退讓，還是反過來指出對方的遊戲。', answer: '六句依序為：反擊、假裝讓步、防守、反擊、假裝讓步、防守。' },            '3-2': { hint: '薩黑荑妮的公主身分沒有可證實的硬證據，成立的是社交圈願意相信的表演。', answer: '「可被證實」不要放任何東西；把社交表演、名字、氣派、流言等放入「社交圈願意相信」；無法查證的細節放入「完全無法確認」。最後答案重點：身分靠眾人願意相信與共同表演成立。' },            '3-3': { hint: '先打蚊子讓距離逐步縮短；沙灘上的靠近不是單純浪漫，而是界線的試探。', answer: '打完所有蚊子後，距離降到安全範圍，即可推進到下一關。' },            '4-1': { hint: '從原文中找到柳原說的關鍵詩句：死生契闊，與子相悅，執子之手，與子偕老。再把這份「一生一世」的暗號轉成圖形數字。', answer: '選出圖形數字 1314。' },            '4-2': { hint: '先接電話，再讓兩個人的月亮位置接近，但不要讓噪音與壓力失控。', answer: '先接起電話，調整流蘇與柳原的月亮滑桿到接近位置，並用安靜／沉默類操作降低噪音後確認。' },            '4-3': { hint: '不要只看眼前安全，這是流蘇用婚姻與名聲做籌碼的長局。', answer: '在談判中選擇能提高主導權、避免流言失控、並逼近婚姻承諾的選項；成功守住足夠籌碼即可過關。' },            '5-1': { hint: '先在圖上把「藥」與「藥罐」組合，再把組合後的藥、船票、電報交給柳原。之後要在照片字影中找出藥瓶的象徵意象。', answer: '先組合「藥」與「藥罐」，再交付組合後的藥、船票、電報。接著把三個轉鈕刻度依序調到：4 綠／6 玻璃／5 雨衣，取得遮色片後把它疊到照片上，就會顯示「你是醫我的藥」輸入柳原需要的藥為「白流蘇」。' },            '5-2': { hint: '房間先不要急著只點餅乾；請先把圖上的熱區全翻找完，再從下方物資中挑出真正能撐下去的餅乾。到淺水灣後也要先蒐集所有物資，再選能分給兩人的食物。', answer: '房間關鍵餅乾選：裝餅乾的盒子。淺水灣食物選：兩塊蘇打餅乾、兩塊方糖。' },            '5-2-babington': { hint: '請先從原文確認三道菜名，再打開食譜回推食材。答案不是所有食譜食材，而是只屬於這三道菜的六個關鍵食材。', answer: '三道菜是：馬來菜、油炸沙袋、咖哩魚。食材選：魚、咖哩粉、椰汁、沙袋、油、香料。' },            '5-3': { hint: '菜名本身藏了三個線索：做法、食材、樣態。請拆開「清蒸蠔湯」三個部分。', answer: '選：烹調方式「清蒸」、主要食材「小蠔」、食品樣態「湯」。新頁面需依正確烹煮順序點圖：洗淨小蠔→添入清湯→上鍋清蒸→盛出上桌。' }        };        function escapeHTML(value) {            return String(value).replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));        }        let pendingAssistRequest = null;        function openAssistModal(title, body, costText, mode = 'info') {            const modal = document.getElementById('assist-modal');            const actions = document.getElementById('assist-modal-actions');            document.getElementById('assist-modal-title').innerText = title;            document.getElementById('assist-modal-cost').innerText = costText || '';            document.getElementById('assist-modal-body').innerHTML = escapeHTML(body).replace(/\n/g, '<br>');            if (actions) {                if (mode === 'confirm') {                    actions.innerHTML = `                        <button onclick="confirmAssistOpen()" class="btn-gold px-8 py-2 rounded-full font-bold">確認點開</button>                        <button onclick="cancelAssistOpen()" class="px-8 py-2 rounded-full font-bold bg-stone-700/70 text-stone-100 border border-stone-500/50 hover:bg-stone-600 transition">我再想想</button>`;                } else {                    actions.innerHTML = `<button onclick="closeAssistModal()" class="btn-gold px-8 py-2 rounded-full font-bold">知道了</button>`;                }            }            modal.style.display = 'flex';        }        function closeAssistModal() {            document.getElementById('assist-modal').style.display = 'none';        }        function openAssist(type) {            const stage = gameState.currentStage;            const data = assistContent[stage];            const label = type === 'hint' ? '提示' : '解答';            if (!data || !data[type]) {                pendingAssistRequest = null;                openAssistModal('目前沒有可用' + label, '這一頁是關卡首頁、過場或結算畫面，不會扣分。', '未扣分');                return;            }            const cost = type === 'hint' ? 10 : 30;            pendingAssistRequest = { stage, type, cost, label, content: data[type] };            openAssistModal(                '扣分確認',                `你即將開啟「${label}」。\n\n開啟後會扣除 ${cost} 分，且同一關重複開啟仍會再次扣分。\n\n確定要點開嗎？`,                `尚未扣分｜確認後才會扣 ${cost} 分`,                'confirm'            );        }        function confirmAssistOpen() {            const req = pendingAssistRequest;            if (!req) {                openAssistModal('沒有待確認項目', '目前沒有需要開啟的提示或解答。', '未扣分');                return;            }            if (gameState.currentStage !== req.stage) {                pendingAssistRequest = null;                openAssistModal('關卡已切換', '你已經離開原本的關卡，這次不扣分。請在目前關卡重新點選提示或解答。', '未扣分');                return;            }            loseChips(req.cost, req.type === 'hint' ? '開啟提示' : '開啟解答');            pendingAssistRequest = null;            openAssistModal(req.label, req.content, `已扣 ${req.cost} 分｜同一關重複開啟仍會再次扣分`);        }        function cancelAssistOpen() {            pendingAssistRequest = null;            closeAssistModal();        }        function updateAssistUI() {            const stage = gameState.currentStage || 'home';            const stageLabel = stageNames[stage] || stage;            const playerEl = document.getElementById('player-title-display');            const stageEl = document.getElementById('current-stage-display');            if (playerEl) playerEl.innerText = gameState.playerTitle || '玩家';            if (stageEl) stageEl.innerText = stageLabel;            const hintBtn = document.getElementById('btn-hint');            const answerBtn = document.getElementById('btn-answer');            const hasAssist = !!assistContent[stage];            if (hintBtn) hintBtn.disabled = !hasAssist;            if (answerBtn) answerBtn.disabled = !hasAssist;            const prevBtn = document.getElementById('btn-prev-stage');            if (prevBtn) prevBtn.disabled = !getPreviousStageTarget();        }        function getPreviousStageTarget() {            const current = gameState.currentStage;            if (!current || current === '1-intro') return '';            if (current === 'complete') {                if (gameState.level === 5) return '5-3-wedding';                if (gameState.level >= 1 && gameState.level <= 4) return `${gameState.level}-3`;            }            const idx = stageSequence.indexOf(current);            if (idx > 0) return stageSequence[idx - 1];            return '';        }        function goPreviousStage() {            const target = getPreviousStageTarget();            if (!target) return showMessage('目前已在最前面的關卡。');            transitionTo(target);        }        const rewards = {            1: [{ id: 'medicine_bottle', label: '藥瓶', icon: '🧴' }],            2: [{ id: 'medicine', label: '藥', icon: '💊' }],            3: [{ id: 'recipe', label: '食譜', icon: '📜' }],            4: [{ id: 'ticket', label: '船票（前往香港）', icon: '🎫' }, { id: 'telegram', label: '電報（乞來港）', icon: '✉️' }]        };        function hasItem(id) { return gameState.inventory.some(item => item.id === id); }        function awardLevelReward(level) {            const list = rewards[level] || [];            list.forEach(item => { if (!hasItem(item.id)) gameState.inventory.push(item); });            updateInventorySummary();            return list;        }        function updateInventorySummary() {            const el = document.getElementById('inventory-summary');            if (!el) return;            el.innerText = gameState.inventory.length ? gameState.inventory.map(i => i.icon + i.label.replace('（前往香港）','').replace('（乞來港）','')).join('、') : '無';        }        function formatGameElapsed(ms) {            const totalSeconds = Math.max(0, Math.floor((Number(ms) || 0) / 1000));            const hours = Math.floor(totalSeconds / 3600);            const minutes = Math.floor((totalSeconds % 3600) / 60);            const seconds = totalSeconds % 60;            if (hours > 0) return `${hours} 小時 ${String(minutes).padStart(2, '0')} 分 ${String(seconds).padStart(2, '0')} 秒`;            return `${minutes} 分 ${String(seconds).padStart(2, '0')} 秒`;        }        function getGameElapsedText() {            const start = gameState.gameStartTime || Date.now();            const end = gameState.gameEndTime || Date.now();            return formatGameElapsed(end - start);        }        function renderRewardText(level) {            const list = rewards[level] || [];            if (!list.length) return '';            return '<div class="mt-6 flex flex-wrap gap-3 justify-center">' + list.map(i => `<span class="reward-chip">${i.icon} 獲得：${i.label}</span>`).join('') + '</div>';        }        function openRecipe() {            const title = document.getElementById('modal-title');            const desc = document.getElementById('modal-desc');            const btn = document.getElementById('modal-confirm-btn');            title.innerText = '食譜';            desc.innerHTML = `                <div id="recipe-flip" class="recipe-flip-card text-left">                    <div class="recipe-flip-inner">                        <div class="recipe-page-face">                            <h3 class="text-2xl font-bold mb-4 text-center">菜名</h3>                            <div class="grid grid-cols-2 gap-x-4 gap-y-2 text-base leading-7">                                <div>紅燒肉</div><div>醃篤鮮</div>                                <div>清蒸蠔湯</div><div>水晶蝦仁</div>                                <div>紅燒烤麩</div><div>生煸草頭</div>                                <div>青魚下巴甩水</div><div>清蒸大閘蟹</div>                                <div>馬來菜</div><div>油炸沙袋</div>                                <div>麻婆豆腐</div><div>咖哩魚</div>                            </div>                            <p class="mt-6 text-center text-sm opacity-70">點擊書頁翻面</p>                        </div>                        <div class="recipe-page-face recipe-page-back">                            <h3 class="text-2xl font-bold mb-4 text-center">做法</h3>                            <div class="recipe-line"><strong>紅燒肉</strong><span>豬肉切塊，過油，加醬色與糖，慢火收汁。</span></div>                            <div class="recipe-line"><strong>醃篤鮮</strong><span>豬肉、火腿與筍同煮，湯要慢慢熬出鮮味。</span></div>                            <div class="recipe-line"><strong>清蒸蠔湯</strong><span>蠔洗淨，薑絲去腥，清湯上鍋，略蒸即成。</span></div>                            <div class="recipe-line"><strong>水晶蝦仁</strong><span>蝦仁去筋，蛋清上漿，清油滑熟。</span></div>                            <div class="recipe-line"><strong>紅燒烤麩</strong><span>烤麩泡透，擠乾，與醬油糖汁同燒。</span></div>                            <div class="recipe-line"><strong>生煸草頭</strong><span>旺火熱油，草頭下鍋，酒香一起即起。</span></div>                            <div class="recipe-line"><strong>青魚下巴甩水</strong><span>魚下巴洗淨，醬燒，湯汁濃後起鍋。</span></div>                            <div class="recipe-line"><strong>清蒸大閘蟹</strong><span>蟹洗淨，薑醋備好，隔水蒸熟。</span></div>                            <div class="recipe-line"><strong>馬來菜</strong><span>香料磨細，椰汁入鍋，慢火煮至香氣浮起。</span></div>                            <div class="recipe-line"><strong>油炸沙袋</strong><span>沙袋切妥，裹粉，下油鍋炸至金黃。</span></div>                            <div class="recipe-line"><strong>麻婆豆腐</strong><span>豆腐切方，辣油豆瓣同燒，花椒收尾。</span></div>                            <div class="recipe-line"><strong>咖哩魚</strong><span>魚切段，咖哩粉與椰汁同煮，收成濃汁。</span></div>                            <p class="mt-4 text-center text-sm opacity-70">點擊書頁翻回</p>                        </div>                    </div>                </div>`;            btn.onclick = closeModal;            btn.innerText = '收起食譜';            document.getElementById('detail-modal').style.display = 'flex';            setTimeout(() => {                const card = document.getElementById('recipe-flip');                if (card) card.onclick = () => card.classList.toggle('flipped');            }, 0);        }        // --- Background Music ---        const BGM_DIRECT_URL = 'assets/audio/x3yirk.mp3';        let bgmWanted = true;        let bgmStarted = false;        function getBgmAudio() {            const audio =